function SlicerGroup({ title, options, selected, onToggle, onShowAll, counts }) {
  const isAll = selected.length === options.length;
  return (
    <div style={{ flex: '1 1 220px', minWidth: 200 }}>
      <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: '0.06em', color: '#8993BC', textTransform: 'uppercase', marginBottom: 7 }}>
        {title}
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
        {onShowAll && (
          <Chip active={isAll} onClick={onShowAll}>
            ทั้งหมด
          </Chip>
        )}
        {options.map((opt) => (
          <Chip key={opt} active={!isAll && selected.includes(opt)} onClick={() => onToggle(opt)} count={counts ? counts[opt] || 0 : undefined}>
            {opt}
          </Chip>
        ))}
      </div>
    </div>
  );
}

function MultiSelectDropdown({ title, options, selected, onToggle, onSelectAll, onClearAll, counts }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    function handleClick(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  const allSelected = selected.length === options.length;
  const summary = allSelected ? 'ทั้งหมด' : selected.length + ' / ' + options.length + ' เลือก';

  return (
    <div ref={ref} style={{ position: 'relative', flex: '1 1 100%' }}>
      <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: '0.06em', color: '#8993BC', textTransform: 'uppercase', marginBottom: 7 }}>
        {title}
      </div>
      <button
        onClick={() => setOpen((o) => !o)}
        style={{
          width: '100%', maxWidth: 420, textAlign: 'left', padding: '9px 14px', borderRadius: 9,
          border: '1px solid #D9DEF0', background: '#FBFBFE', fontSize: 13, fontWeight: 600,
          color: '#242C4D', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10,
        }}
      >
        <span>{summary}</span>
        <span style={{ color: '#8993BC', fontSize: 11, transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s ease' }}>▾</span>
      </button>

      {open && (
        <div style={{
          position: 'absolute', top: '100%', left: 0, marginTop: 6, width: 380, maxWidth: '90vw',
          background: '#FFFFFF', border: '1px solid #E6E9F7', borderRadius: 12,
          boxShadow: '0 8px 24px rgba(25,37,148,0.15)', zIndex: 20, padding: 10,
        }}>
          <div style={{ display: 'flex', gap: 8, marginBottom: 8, paddingBottom: 8, borderBottom: '1px solid #F0F1FA' }}>
            <button onClick={onSelectAll} style={{ fontSize: 11.5, fontWeight: 700, color: '#192594', background: 'none', border: 'none', cursor: 'pointer', padding: '2px 6px' }}>
              เลือกทั้งหมด
            </button>
            <button onClick={onClearAll} style={{ fontSize: 11.5, fontWeight: 700, color: '#8993BC', background: 'none', border: 'none', cursor: 'pointer', padding: '2px 6px' }}>
              ล้างทั้งหมด
            </button>
          </div>
          <div style={{ maxHeight: 260, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: 2 }}>
            {options.map((opt) => (
              <label
                key={opt}
                style={{
                  display: 'flex', alignItems: 'center', gap: 9, padding: '7px 8px', borderRadius: 7,
                  cursor: 'pointer', fontSize: 12.5, color: '#242C4D',
                  background: selected.includes(opt) ? '#F4F5FB' : 'transparent',
                }}
              >
                <input type="checkbox" checked={selected.includes(opt)} onChange={() => onToggle(opt)} />
                <span style={{ flex: 1 }}>{opt}</span>
                <span style={{ fontSize: 10.5, fontWeight: 700, color: '#8993BC' }}>{counts ? counts[opt] || 0 : ''}</span>
              </label>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

